448	func (c Client) roundTrip(ctx context.Context, req request) (Reply, error) {
449		if !Supported() {
450			return Reply{}, ErrUnsupported
451		}
452		if info, err := os.Lstat(c.Dir); err == nil {
453			if err := checkDir(c.Dir, info); err != nil {
454				return Reply{}, err
455			}
456		} else if errors.Is(err, os.ErrNotExist) {
457			return Reply{}, ErrNoRuntime
458		} else {
459			return Reply{}, err
460		}
461		path := SocketPath(c.Dir, c.Identity)
462		if _, err := checkSocket(path); err != nil {
463			if errors.Is(err, os.ErrNotExist) {
464				return Reply{}, ErrNoRuntime
465			}
466			return Reply{}, err
467		}
468		dialer := net.Dialer{Timeout: 2 * time.Second}
469		conn, err := dialer.DialContext(ctx, "unix", path)
470		if err != nil {
471			// Nobody answers: a stale endpoint is no runtime.
472			return Reply{}, ErrNoRuntime
473		}
474		defer conn.Close()
475		if uc, ok := conn.(*net.UnixConn); ok {
476			if uid, err := peerUID(uc); err != nil || int(uid) != os.Getuid() {
477				return Reply{}, &UnsafeError{path, "the process that answers is not the user's"}
478			}
479		}
480		_ = conn.SetDeadline(time.Now().Add(requestDeadline + time.Duration(req.DrainMS)*time.Millisecond))
481		raw, _ := json.Marshal(req)
482		if _, err := conn.Write(append(raw, '\n')); err != nil {
483			return Reply{}, err
484		}
485		line, err := bufio.NewReader(io.LimitReader(conn, maxRequest)).ReadBytes('\n')
486		if err != nil && len(line) == 0 {
487			return Reply{}, err
488		}
489		var reply Reply
490		if err := json.Unmarshal(line, &reply); err != nil {
491			return Reply{}, fmt.Errorf("the runtime answered something that is not a reply: %w", err)
492		}
493		return reply, nil
494	}
