496	// Handshake attaches: it sends the identity and gets the state of the runtime back, or an
497	// IncompatibleError naming each field that differs.
498	func (c Client) Handshake(ctx context.Context) (Reply, error) {
499		id := c.Identity
500		reply, err := c.roundTrip(ctx, request{Op: "handshake", Identity: &id})
501		if err != nil {
502			return Reply{}, err
503		}
504		if len(reply.Mismatch) > 0 {
505			sort.Strings(reply.Mismatch)
506			return reply, &IncompatibleError{Mismatch: reply.Mismatch}
507		}
508		if !reply.OK {
509			return reply, errors.New(reply.Error)
510		}
511		return reply, nil
512	}
