525	// WaitReleased returns when the endpoint of the identity can be taken: nothing answers and the
526	// previous holder has released its lock, or the timeout passed.
527	func (c Client) WaitReleased(ctx context.Context, timeout time.Duration) bool {
528		if !Supported() {
529			return true
530		}
531		end := time.Now().Add(timeout)
532		for time.Now().Before(end) && ctx.Err() == nil {
533			if _, err := c.Status(ctx); errors.Is(err, ErrNoRuntime) {
534				if unlock, err := lockEndpoint(SocketPath(c.Dir, c.Identity) + ".lock"); err == nil {
535					unlock()
536					return true
537				}
538			}
539			time.Sleep(20 * time.Millisecond)
540		}
541		return false
542	}
