544	// Stop asks the runtime to drain within the deadline and exit.
545	func (c Client) Stop(ctx context.Context, drain time.Duration) (Reply, error) {
546		return c.roundTrip(ctx, request{Op: "stop", DrainMS: int(drain.Milliseconds())})
547	}
